// RuleRunner game data — warhammer-40k
// Lives at data/warhammer-40k.js in the repo, loaded by index.html.
// Independently-written rule summaries — not copied from any rulebook.
// This file only needs GAMES to already exist as an object (declared in
// index.html before this file is loaded). It adds exactly one key to it.
//
// To add or edit a rule: find the entry by its `id` and edit its `text`/
// `keywords`/`phase` fields, or copy an existing entry as a template for a
// new one. See RULES-PROCESS.md for the full process.

GAMES["warhammer-40k"] = {
    name: "Warhammer 40,000 (11th Ed.)",
    example: "can I overwatch that charge?",
    infoUrl: "https://wahapedia.ru/wh40k11ed/the-rules/core-rules/",
    howToPlay: [
      { heading:"Objective", text:"Command an army of miniatures and score more Victory Points than your opponent, mainly by holding and contesting mission objectives rather than by wiping out their army." },
      { heading:"Setup", text:"Both players build an army to an agreed points limit — 2,000 points is the most common standard game size — using their faction's datasheets. Pick a mission, which sets the deployment map and objectives, then alternate placing units inside your own deployment zone before turn one." },
      { heading:"Command Phase", text:"First, gain 1 Command Point. Then make a Battle-shock roll for any unit at or below half-strength, or already Battle-shocked — a Battle-shocked unit has its Objective Control reduced to '-', can't be targeted by Stratagems, and can't start actions. Finally, resolve any other Command-phase abilities or Stratagems, which happen after Battle-shock so they can't retroactively help a unit avoid it." },
      { heading:"Movement Phase", text:"Every unit — including those in Strategic Reserves — becomes eligible to move. One at a time, give each unit a Normal Move, an Advance, a Fall Back, or have it Remain Stationary; a unit in Reserves instead makes an Ingress Move to arrive, or Remains Stationary if it's not ready yet." },
      { heading:"Shooting Phase", text:"One at a time, pick an eligible unit — one that didn't Advance or Fall Back this turn, unless an ability says otherwise — and choose one or more valid, visible targets within range. Resolve that unit's attacks (hit rolls, wound rolls, saves, damage) completely before picking the next unit to shoot." },
      { heading:"Charge Phase", text:"One at a time, declare a charge with an eligible unit, roll 2D6 for distance, select your targets, and move the unit to end Engaged with all of them. A successful charge grants Fights First until the end of the turn, and the phase isn't interrupted by shooting." },
      { heading:"Fight Phase", text:"Units that charged this turn, and any Fights First units, are chosen to fight before everyone else. After that, the active player and their opponent alternate choosing one eligible unit at a time to fight until none remain — each pile in, make their attacks, then consolidate before the next unit is chosen." },
      { heading:"Scoring As You Go", text:"Most missions score Primary Objectives at the start of your Command phase based on which objectives your Objective Control total currently holds, plus Secondary Objectives from a separate deck or fixed list you choose before the game or draw as you play." },
      { heading:"Winning", text:"Missions typically run 5 battle rounds. After the final one, whoever has scored the most total Victory Points from Primary and Secondary Objectives wins — a draw is possible if scores are tied." },
      { heading:"Quick Tip", text:"Objective Control usually decides games more than casualties do — a cheap unit quietly sitting on an objective is often winning you the game harder than an expensive unit dealing damage across the board." },
    ],
    rules: [
      { id:"w40k-move", title:"Move", phase:"Movement", linkTerm:"Normal Move", keywords:["move","movement phase","normal move"],
        text:"Each unit can move up to its Move characteristic in inches. Models can move freely through friendly models, and rotating a model on the spot costs no movement." },
      { id:"w40k-advance", title:"Advance", phase:"Movement", linkTerm:"Advance", keywords:["advance","advancing"],
        text:"Roll a D6 and add it to the unit's Move for this phase. Advancing locks out shooting and charging this turn unless a specific ability overrides it." },
      { id:"w40k-fallback", title:"Fall Back", phase:"Movement", linkTerm:"Fall Back", keywords:["fall back","falling back"],
        text:"A unit within Engagement Range of an enemy can fall back to disengage. If it isn't Battle-shocked it falls back with no downside; if it is Battle-shocked it must make a Desperate Escape instead. Either way it can't shoot or charge this turn unless an ability says otherwise." },
      { id:"w40k-desperate-escape", title:"Desperate Escape", phase:"Movement", linkTerm:"Desperate Escape", keywords:["desperate escape"],
        text:"Forced on a Battle-shocked unit that falls back: make a Hazard Roll for each model, and each model can move through enemy models while doing so." },
      { id:"w40k-difficult-terrain", title:"Difficult Terrain", phase:"Movement", keywords:["difficult terrain","dense terrain"],
        text:"Difficult ground effects remain feature-specific rather than universal — check the printed rules on the terrain feature itself, alongside Cover and Hidden for its other effects." },
      { id:"w40k-deep-strike", title:"Deep Strike", phase:"Movement", keywords:["deep strike","deep striking"],
        text:"Deep Strike is no longer its own universal move type in 11th edition — the official list of move types doesn't include it. Where it still exists, it's a datasheet-specific ability layered on top of the standard Ingress Move used from Strategic Reserves, usually loosening the normal arrival restrictions. Check the specific unit's own printed ability for its exact effect." },
      { id:"w40k-strategic-reserves", title:"Strategic Reserves", phase:"Movement", linkTerm:"Strategic Reserves", keywords:["strategic reserves","in reserve","reserves"],
        text:"Units placed in Strategic Reserves don't start on the battlefield. During your Movement phase they can Remain Stationary or arrive with an Ingress Move — there's no separate Reinforcements step to wait for, they're eligible to act like any other unit as soon as the phase begins. The total points value you can hold in reserve is capped at roughly half your army's total points." },
      { id:"w40k-clar-reserves-deadline", title:"Reserves Are Destroyed If Not Arrived by Battle Round 3", phase:"Clarification", relatedTo:"w40k-strategic-reserves", keywords:["reserves deadline","when do reserves have to arrive"],
        text:"A unit that started the game in Strategic Reserves and still hasn't arrived by the end of battle round 3 is destroyed. A unit embarked in a Transport that itself arrived from reserves is exempt from this — it just hasn't disembarked yet." },
      { id:"w40k-ingress-move", title:"Ingress Move", phase:"Movement", linkTerm:"Ingress Move", keywords:["ingress move","ingress moves"],
        text:"An Ingress Move is how a unit in Strategic Reserves arrives on the battlefield: set it up wholly within 6 inches of a battlefield edge and more than 8 inches from every enemy model. A unit that makes an Ingress Move can't make any other type of move until your next Charge phase, and reserves can't arrive at all before the second battle round unless a rule says otherwise." },
      { id:"w40k-overwatch", title:"Overwatch", phase:"Shooting", linkTerm:["Fire Overwatch","Overwatch"], keywords:["overwatch"],
        text:"The Fire Overwatch Stratagem is used at the end of your opponent's Movement phase, not reactively during it. It lets one friendly unengaged unit (excluding Titanic units) shoot at one visible enemy unit within 24\", hitting only on unmodified 6s with no rerolls on the hit roll." },
      { id:"w40k-shoot", title:"Shoot", phase:"Shooting", keywords:["shooting phase","shoot","ranged attack","to hit","hit roll"],
        text:"Pick an eligible unit and one or more valid targets in range and visible. Roll to hit — applying the -1 penalty if the target is in Cover — then roll to wound, the opponent saves, and you resolve damage." },
      { id:"w40k-shooting-types", title:"Shooting Types — Normal, Assault, Close-Quarters, Indirect", phase:"Shooting", keywords:["shooting types","types of shooting","close-quarters shooting","indirect shooting"],
        text:"There are four shooting types. Normal Shooting needs your unit unengaged and not having Advanced. Assault Shooting is for a unit that Advanced and has Assault weapons. Close-Quarters Shooting lets an engaged unit with Close-Quarters weapons (or any Monster/Vehicle) shoot the unit it's fighting — though a Monster/Vehicle's other weapons take a -1 penalty unless they're also Close-Quarters. Indirect Shooting lets Indirect Fire weapons target units with no line of sight, but can't reroll hit rolls and needs an unmodified 6 to hit, or a 4+ instead if your unit Remained Stationary and the target is visible to another friendly unit." },
      { id:"w40k-line-of-sight", title:"Line of Sight", phase:"Shooting", keywords:["line of sight","visible","can i see"],
        text:"A model can see another model if any part of it is visible when you look from the shooting model's location, subject to the Hidden status overriding visibility for qualifying units in terrain." },
      { id:"w40k-cover", title:"Cover", phase:"Shooting", linkTerm:"Cover", keywords:["cover","in cover","benefit of cover"],
        text:"A unit has the benefit of Cover against a ranged attack if every model in it either has the Infantry, Beast, or Swarm keyword and is within a terrain area, or isn't fully visible to the attacker due to intervening terrain. Monster and Vehicle models don't qualify through the first path — occupying a terrain feature's footprint alone doesn't give them Cover — but can still gain it through the second path if genuinely obscured by intervening terrain. Cover worsens the attacker's Ballistic Skill by 1, rather than boosting the target's save." },
      { id:"w40k-clar-monster-vehicle-cover", title:"Monsters and Vehicles Don't Get Cover Just by Standing in Terrain", phase:"Clarification", relatedTo:"w40k-cover", keywords:["monster cover","vehicle cover","does my tank get cover","does my knight get cover"],
        text:"Unlike Infantry, Beasts, and Swarms, a Monster or Vehicle doesn't gain the benefit of Cover simply because its base overlaps a terrain feature's footprint. It can still gain Cover the way any unit can — by being genuinely obscured from the attacker's line of sight by intervening terrain — but standing inside a ruin's footprint alone isn't enough for a model that size." },
      { id:"w40k-plunging-fire", title:"Plunging Fire", phase:"Shooting", linkTerm:"Plunging Fire", keywords:["plunging fire"],
        text:"An attack gets +1 to its Ballistic Skill if the target unit contains a model at ground level, and either: the firing model is on a terrain feature 3 inches or more in height, or the firing model has the Towering keyword and the target is within 12 inches." },
      { id:"w40k-hidden", title:"Hidden", phase:"Shooting", linkTerm:"Hidden", keywords:["hidden status","is it hidden","hidden"],
        text:"An Infantry, Beast, or Swarm model gains the Hidden status if it's within a terrain area containing a Light or Dense terrain feature and its unit made no ranged attacks this turn or last turn. Enemy models more than 15 inches away can't target it at all." },
      { id:"w40k-gone-to-ground", title:"Gone to Ground", phase:"Shooting", relatedTo:"w40k-hidden", keywords:["gone to ground"],
        text:"A Hidden model that also isn't fully visible specifically because of a Dense terrain feature — and still hasn't made a ranged attack this turn or last — has Gone to Ground. This cuts its detection range from 15 inches down to 12, making it even harder for distant units to target." },
      { id:"w40k-terrain-movement", title:"Terrain & Movement", phase:"Movement", keywords:["terrain and movement","terrain movement","moving through terrain","moving through dense terrain"],
        text:"Exposed and Light terrain features can be moved through freely by any model. Dense terrain features can be moved through horizontally by Infantry, Beast, Swarm, and Mobile models; other models must move vertically to climb any section taller than 2 inches, and can't pass through ceilings or floors while doing so." },
      { id:"w40k-obscuring", title:"Obscuring", phase:"Shooting", keywords:["obscuring terrain","obscuring"],
        text:"A terrain area containing a Light or Dense feature is obscuring. If every line of sight between two models crosses one or more obscuring terrain areas that neither model is inside, those two models can't see each other at all — this is separate from, and in addition to, the Benefit of Cover rule." },
      { id:"w40k-solid", title:"Solid", phase:"Shooting", keywords:["solid","solid terrain rule","solid rule"],
        text:"Dense terrain features have the Solid rule: line of sight can't be drawn through any enclosed gap in them — doors, windows, small holes — that's 3 inches or less above ground level, no matter how small the opening looks." },
      { id:"w40k-blast", title:"Blast", phase:"Shooting", linkTerm:"Blast", keywords:["blast weapon","blast"],
        text:"Weapons with the Blast ability get +1 attack for every full 5 models in the target unit. Blast weapons can't be used to target a unit within Engagement Range of any of your units." },
      { id:"w40k-rapid-fire", title:"Rapid Fire", phase:"Shooting", linkTerm:"Rapid Fire", keywords:["rapid fire"],
        text:"A weapon with Rapid Fire X gets +X attacks when the target is within half the weapon's range." },
      { id:"w40k-sustained-hits", title:"Sustained Hits", phase:"Shooting", linkTerm:"Sustained Hits", keywords:["sustained hits","sustained hits monster/vehicle","sustained hits non-monster/vehicle"],
        text:"On a Critical Hit (an unmodified 6 to hit, unless stated otherwise), the attack scores that many additional hits automatically — Sustained Hits X means X extra hits." },
      { id:"w40k-lethal-hits", title:"Lethal Hits", phase:"Shooting", linkTerm:"Lethal Hits", keywords:["lethal hits","lethal hits non-monster/vehicle","lethal hits monster/vehicle"],
        text:"A Critical Hit can automatically wound the target, skipping the need to roll to wound for that attack — you can choose not to, though, if you'd rather roll normally and try for a Devastating Wounds critical instead." },
      { id:"w40k-devastating-wounds", title:"Devastating Wounds", phase:"Shooting", linkTerm:"Devastating Wounds", keywords:["devastating wounds","devastating wounds infantry","devastating wounds monster/vehicle"],
        text:"A Critical Wound (an unmodified 6 to wound) is allocated as a mortal wound instead of normal damage, and armour or invulnerable saves can't be taken against it." },
      { id:"w40k-charge", title:"Charge", phase:"Charge", keywords:["charge","charge phase","declare a charge","charging"],
        text:"Declare a charge if your unit is within 12 inches of an enemy, unengaged, and didn't Advance or Fall Back this turn. Roll 2D6 for charge distance, then select one or more enemy units within 12 inches and within that distance as your targets, moving to end Engaged with all of them." },
      { id:"w40k-clar-charge-roll-of-2", title:"A Charge Roll of 2 Always Fails", phase:"Clarification", relatedTo:"w40k-charge", keywords:["charge roll of 2","can a charge of 2 succeed"],
        text:"Without a modifier, rolling a 2 on a charge (double 1s) can never succeed. A unit can't already be within the 2-inch Engagement Range when it attempts a charge, so the minimum distance that could ever complete one is always higher than 2 — a roll of 2 is a guaranteed failed charge." },
      { id:"w40k-heroic-intervention", title:"Heroic Intervention", phase:"Charge", linkTerm:"Heroic Intervention", keywords:["heroic intervention"],
        text:"Heroic Intervention (1CP, Core Stratagem) triggers just after an enemy unit ends a Charge move. Pick one of your units within 6 inches of that enemy unit that would itself be eligible to charge it — your unit now declares and resolves a charge targeting only that enemy unit, as if it were your own Charge phase. Vehicles can only use this if they're a Walker, and even a successful charge this way grants no Charge bonus (no Fights First)." },
      { id:"w40k-command-reroll", title:"Command Re-Roll", phase:"General", linkTerm:"Command Re-Roll", keywords:["command re-roll","command reroll"],
        text:"Command Re-Roll (1CP, Core Stratagem) can be used in any phase, immediately after a unit or model from your army makes an Advance, Charge, Hit, Wound, Damage, or Attacks-count roll, a Desperate Escape test, a Hazard roll, or a saving throw. You re-roll that single roll or test." },
      { id:"w40k-insane-bravery", title:"Insane Bravery", phase:"Command", linkTerm:"Insane Bravery", keywords:["insane bravery"],
        text:"Insane Bravery (1CP, Core Stratagem) is used just before taking a Battle-shock test for one of your units, making that unit automatically pass. You can only use it once per battle." },
      { id:"w40k-rapid-ingress", title:"Rapid Ingress", phase:"Movement", linkTerm:"Rapid Ingress", keywords:["rapid ingress"],
        text:"Rapid Ingress (1CP, Core Stratagem) lets one of your units in Strategic Reserves make an Ingress Move at the end of your opponent's Movement phase, instead of waiting for your own. It can't be used in the first battle round." },
      { id:"w40k-explosives", title:"Explosives", phase:"Shooting", linkTerm:"Explosives", keywords:["explosives","grenade stratagem","grenades stratagem"],
        text:"Explosives (1CP, Core Stratagem, formerly called Grenades) lets an eligible, unengaged unit with the Grenades ability target a visible enemy unit within 8 inches. Roll six D6 — each result of 4 or more inflicts 1 mortal wound on that enemy unit." },
      { id:"w40k-counteroffensive", title:"Counteroffensive", phase:"Fight", linkTerm:"Counteroffensive", keywords:["counteroffensive","counter offensive","counter-offensive"],
        text:"Counteroffensive (2CP, Core Stratagem) is used just after an enemy unit fights. Pick one of your engaged units that hasn't fought yet this phase, and it fights next — jumping the normal alternating fight order." },
      { id:"w40k-crushing-impact", title:"Crushing Impact", phase:"Charge", linkTerm:["Crushing Impact","Tank Shock"], keywords:["crushing impact","tank shock"],
        text:"Crushing Impact (1CP, Core Stratagem, formerly Tank Shock) triggers just after one of your Monster or Vehicle units ends a Charge move. Pick an engaged enemy unit and one engaged model from your unit, then roll a number of D6 equal to that model's Toughness: each 5+ inflicts 1 mortal wound on the enemy, to a maximum of 6 — but each roll of 1 inflicts a mortal wound on your own unit instead." },
      { id:"w40k-epic-challenge", title:"Epic Challenge", phase:"Fight", linkTerm:"Epic Challenge", keywords:["epic challenge"],
        text:"Epic Challenge (1CP, Core Stratagem) triggers just after a friendly Character unit is selected to fight. Pick one Character model in that unit — until the end of the phase, its melee attacks gain the Precision ability, letting you allocate them to a specific enemy model instead of the unit's own choice." },
      { id:"w40k-smokescreen", title:"Smokescreen", phase:"Shooting", linkTerm:"Smokescreen", keywords:["smokescreen","smoke screen"],
        text:"Smokescreen (1CP, Core Stratagem) is used at the start of your opponent's Shooting phase, targeting one of your own units with the Smoke ability. Until the end of the phase, that unit — and any unit not fully visible to the attacker because of it — gets the Benefit of Cover against incoming attacks." },
      { id:"w40k-attached-units", title:"Attached Units", phase:"General", linkTerm:"Attached Units", keywords:["attached unit","attached units","character attached"],
        text:"A Character with the Leader ability can attach to a matching Bodyguard unit, forming a single Attached unit for almost all rules purposes — they move, shoot, and fight together, and use the highest relevant characteristic (like Toughness) among the models present whenever it differs." },
      { id:"w40k-lone-operative", title:"Lone Operative", phase:"General", linkTerm:"Lone Operative", keywords:["lone operative"],
        text:"Lone Operative means a model can only be chosen as the target of a ranged attack if the attacking model is within a stated distance of it — 12 inches by default, unless the ability itself specifies otherwise. It has no effect on being targeted in melee." },
      { id:"w40k-fight", title:"Fight", phase:"Fight", keywords:["fight phase","melee","fighting","to wound","wound roll","fight"],
        text:"Fights First units are selected to fight before other eligible units, then remaining units alternate between players. Each fighting model can move up to 3 inches (pile in), then makes its melee attacks." },
      { id:"w40k-fights-first", title:"Fights First", phase:"Fight", linkTerm:"Fights First", keywords:["fights first"],
        text:"A unit that made a charge move this turn has the Fights First ability until the end of the turn. Fights First units are selected to fight before any other eligible unit in the Fight phase." },
      { id:"w40k-overrun-fight", title:"Overrun Fight", phase:"Fight", linkTerm:"Overrun Fight", keywords:["overrun","overrun fight","unengaged fight"],
        text:"If a unit is eligible to fight but is unengaged — most often because everything it was fighting has already been destroyed — it makes an Overrun Fight instead of simply being skipped. It gets one extra pile-in move (still up to 3 inches, but able to target enemy units within 5 inches since it has nothing to pile toward yet) to drag itself into a fresh engagement, then fights normally. This can pull previously-unengaged enemy units into the fight too, making them eligible to fight this phase — even as Fights First units if they qualify." },
      { id:"w40k-pile-in", title:"Pile In", phase:"Fight", linkTerm:"Pile In", keywords:["pile in","piling in"],
        text:"Before making melee attacks, each model can move up to 3 inches toward the closest enemy model, ending closer to that enemy than where it started. Models already in base contact with an enemy model can't be moved." },
      { id:"w40k-consolidate", title:"Consolidate", phase:"Fight", linkTerm:["Consolidation","consolidate"], keywords:["consolidate","consolidation"],
        text:"After a unit is eligible to fight, its models can make a Consolidation move of up to 3 inches in one of three modes: Ongoing (if still engaged, stay engaged with everything it's fighting), Engaging (if unengaged but within 3\" of an enemy, move to engage one or more of them), or Objective (otherwise, move onto a nearby objective). These are checked in that order, and whichever applies first is mandatory." },
      { id:"w40k-clar-engaging-consolidation-pulls-in", title:"Consolidation Can Drag In New Enemies", phase:"Clarification", relatedTo:"w40k-consolidate", keywords:["consolidate into new enemy","consolidation pulls in new units","ongoing consolidation new enemies"],
        text:"Both Ongoing and Engaging Consolidation can end with your unit engaged with enemy units that haven't fought yet this phase — this was confirmed by errata for Ongoing Consolidation specifically, which many players miss. If that happens, your opponent must select each of those units to fight, one at a time, so consolidating aggressively can hand your opponent fights they wouldn't otherwise have gotten." },
      { id:"w40k-engagement-range", title:"Engagement Range", phase:"Fight", linkTerm:["Engagement Range","Engaged"], keywords:["engagement range"],
        text:"Engagement Range extends 2 inches horizontally and 5 inches vertically from an enemy model. Being within it means a unit is engaged, which restricts falling back and most shooting." },
      { id:"w40k-feel-no-pain", title:"Feel No Pain", phase:"Fight", linkTerm:"Feel No Pain", keywords:["feel no pain","fnp"],
        text:"When a model with Feel No Pain X+ would lose a wound, roll a D6 for each point of damage. On a result of X or more, that point of damage is ignored." },
      { id:"w40k-battle-shock", title:"Battle-shock / Morale", phase:"Command", linkTerm:["Battle-shocked","Battle-shock"], keywords:["battle-shock","battleshock","morale","combat attrition"],
        text:"At the start of the Command phase, make a battle-shock roll for any unit at or below half-strength, or already Battle-shocked: roll 2D6, and it avoids or recovers from Battle-shock if the result is equal to or greater than its Leadership. A Battle-shocked unit has its Objective Control reduced to '-', can't be targeted by Stratagems, and can't start actions." },
      { id:"w40k-objective-control", title:"Objective Control (OC)", phase:"Scoring", linkTerm:"Objective Control", keywords:["objective control","oc","control an objective","holding the objective"],
        text:"An objective is tied to a terrain area. Add up the Objective Control of your models within it: the higher total controls the objective, and a tie leaves it uncontrolled unless it's Secured. A Secured Objective stays under your control even after you leave, until your opponent's control level there exceeds yours." },
      { id:"w40k-detachments", title:"Detachments & Detachment Points", phase:"Army Building", linkTerm:"Detachment Points", keywords:["detachment points","multiple detachments","combine detachments"],
        text:"An army list can combine multiple Detachments within a Detachment Points budget, mixing and matching the Stratagems and Enhancements each one brings, rather than picking a single Detachment for the whole army." },
      { id:"w40k-command-points", title:"Command Points & Stratagems", phase:"Command", linkTerm:["Stratagems","Command Point"], keywords:["command points","cp","stratagem"],
        text:"Command Points are spent to use Stratagems. The same Stratagem can't be used more than once per phase by the same player, and — unless stated otherwise — the same unit can't be targeted by more than one Stratagem in the same phase." },
      { id:"w40k-heal", title:"Heal", phase:"General", linkTerm:"Heal", keywords:["heal","healing","heal x"],
        text:"Heal X (repeated X times): if any model in the unit is missing wounds, restore 1 wound to one such model. If no model is missing wounds but the unit has lost a whole model, instead return one destroyed model to the unit with 1 wound remaining. A model can never be healed beyond its own starting Wounds characteristic — any excess is wasted rather than reviving an extra model." },
      { id:"w40k-invulnerable-save", title:"Invulnerable Save", phase:"General", keywords:["invulnerable save","invuln","invulnerable"],
        text:"An invulnerable save is used instead of a normal armour save and isn't affected by AP. A model uses whichever save is better for a given attack." },
      { id:"w40k-mortal-wounds", title:"Mortal Wounds", phase:"General", keywords:["mortal wounds","mortal wound"],
        text:"Mortal wounds are allocated directly to a unit, removing wounds without any save roll, aside from abilities that explicitly work against mortal wounds." },
      { id:"w40k-terrain-traits", title:"Terrain Traits", phase:"General", keywords:["terrain trait","obscuring","light cover"],
        text:"Terrain features fall into three categories — Exposed, Light, or Dense — each with fixed rules for movement and visibility, replacing 10th edition's Light Cover/Heavy Cover/Obscuring split." },
      { id:"w40k-flying", title:"Flying (FLY keyword)", phase:"Movement", keywords:["flying","fly keyword","flyer movement"],
        text:"A unit with the FLY keyword subtracts 2 inches from its maximum move but ignores vertical distance entirely, letting it pass over terrain and buildings without measuring climbs and drops." },
      { id:"w40k-surge-move", title:"Surge Move", phase:"Movement", linkTerm:"Surge Move", keywords:["surge move","surge moves"],
        text:"A Surge Move is granted by another rule (typically after the unit is shot at or loses models), and that triggering rule states the actual distance — commonly D6 inches. A unit is only eligible if it's unengaged, not Battle-shocked, and hasn't already made a move this phase. It moves toward the closest enemy unit, ending engaged with it if possible or as close as possible if not — but this never counts as having charged, so it doesn't grant Fights First or any charge-triggered bonus like Lance." },
      { id:"w40k-unit-coherency", title:"Unit Coherency", phase:"General", linkTerm:"Unit Coherency", keywords:["unit coherency","coherency"],
        text:"Every model in a unit must be within 2 inches horizontally and 5 inches vertically of at least one other model in that unit, and within 9 inches horizontally and 5 inches vertically of every other model in that unit." },
      { id:"w40k-hazard-roll", title:"Hazard Roll", phase:"General", linkTerm:"Hazard Roll", keywords:["hazard roll"],
        text:"To make a Hazard Roll for a unit, roll a D6 for each model: on a 1-2 the unit suffers 1 mortal wound, or 3 mortal wounds instead if every model in the unit is a Monster or Vehicle." },
      { id:"w40k-twin-linked", title:"Twin-linked", phase:"Weapon Ability", linkTerm:"Twin-linked", keywords:["twin-linked","twin linked"],
        text:"When making an attack with this weapon, you can re-roll the wound roll." },
      { id:"w40k-ignores-cover", title:"Ignores Cover", phase:"Weapon Ability", linkTerm:"Ignores Cover", keywords:["ignores cover"],
        text:"Attacks made with this weapon ignore the -1 to-hit penalty that a target in Cover would otherwise impose." },
      { id:"w40k-indirect-fire", title:"Indirect Fire", phase:"Weapon Ability", linkTerm:"Indirect Fire", keywords:["indirect fire"],
        text:"This weapon can target units it doesn't have line of sight to. Such attacks are made at -1 to hit, and the target always counts as being in Cover against them." },
      { id:"w40k-torrent", title:"Torrent", phase:"Weapon Ability", linkTerm:"Torrent", keywords:["torrent"],
        text:"Attacks made with this weapon automatically hit their target — skip the hit roll entirely." },
      { id:"w40k-melta", title:"Melta", phase:"Weapon Ability", linkTerm:"Melta", keywords:["melta","melta weapon"],
        text:"If the target is within half this weapon's range, add the melta value to the Damage characteristic of each successful wound." },
      { id:"w40k-anti-x", title:"Anti-X", phase:"Weapon Ability", linkTerm:["Anti-Infantry","Anti-Vehicle","Anti-Monster","Anti-Titanic","Anti-Fly","Anti-Psyker","Anti-Chaos","Anti-Character","Anti-Tyranids"], keywords:["anti-infantry","anti-vehicle","anti-monster","anti-x","anti-fly","anti-psyker","anti-chaos","anti-character","anti-tyranids","anti-monster/vehicle"],
        text:"Written as Anti-[Keyword] X+. Against a unit with the named keyword, any wound roll of X or more automatically scores a Critical Wound, regardless of the weapon's actual Strength versus Toughness." },
      { id:"w40k-extra-attacks", title:"Extra Attacks", phase:"Weapon Ability", linkTerm:"Extra Attacks", keywords:["extra attacks"],
        text:"A weapon with this ability is used in addition to a model's other weapons, rather than being selected instead of them." },
      { id:"w40k-precision", title:"Precision", phase:"Weapon Ability", linkTerm:"Precision", keywords:["precision","precision weapon"],
        text:"Successful hits with this weapon can be allocated to a Character model within the target unit, bypassing the normal closest-model wound allocation order." },
      { id:"w40k-lance", title:"Lance", phase:"Weapon Ability", linkTerm:"Lance", keywords:["lance","lance weapon"],
        text:"If the bearer made a charge move this turn, add 1 to wound rolls for this weapon in the Fight phase." },
      { id:"w40k-hazardous", title:"Hazardous", phase:"Weapon Ability", linkTerm:"Hazardous", keywords:["hazardous","hazardous weapon"],
        text:"After a model attacks with this weapon, roll a D6 for each model that did so. On a 1, that model's unit suffers mortal wounds from the weapon overheating or malfunctioning." },
      { id:"w40k-one-shot", title:"One Shot", phase:"Weapon Ability", linkTerm:"One Shot", keywords:["one shot","one-shot","one shot weapon"],
        text:"This weapon can only be selected to shoot with once per battle." },
      { id:"w40k-cleave", title:"Cleave", phase:"Weapon Ability", linkTerm:"Cleave", keywords:["cleave","cleave weapon"],
        text:"Cleave X is the melee equivalent of Blast: add 1 Attack for every 5 models (rounding down) in the target unit, multiplied by X. All of this weapon's attacks must target the same unit to get the bonus — splitting attacks across multiple units forfeits it." },
      { id:"w40k-close-quarters", title:"Close-Quarters", phase:"Weapon Ability", linkTerm:"Close-Quarters", keywords:["close-quarters","close quarters weapon"],
        text:"Functionally similar to Pistol — a Close-Quarters weapon can be fired even while its bearer's unit is within Engagement Range of the enemy, as part of Close-Quarters Shooting." },
      { id:"w40k-psychic", title:"Psychic (weapon ability)", phase:"Weapon Ability", linkTerm:"Psychic", keywords:["psychic weapon","psychic attack"],
        text:"Attacks made with a Psychic weapon ignore all modifiers to Ballistic Skill, Weapon Skill, and the Hit roll — both penalties and bonuses." },
      { id:"w40k-hooked", title:"Hooked", phase:"Weapon Ability", linkTerm:"Hooked", keywords:["hooked","hooked weapon"],
        text:"If this weapon hits a Monster or Vehicle, the bearer's unit gets +2 to its Charge roll against that target for the rest of the turn, and that target can't use Fire Overwatch against the bearer's unit." },
      { id:"w40k-harpooned", title:"Harpooned", phase:"Weapon Ability", linkTerm:"Harpooned", keywords:["harpooned","harpooned weapon"],
        text:"If this weapon hit a Monster or Vehicle this turn, the bearer's unit gets +2 to its Charge roll against that target and must end the charge move engaged with it." },
      { id:"w40k-conversion", title:"Conversion", phase:"Weapon Ability", linkTerm:"Conversion", keywords:["conversion","conversion weapon"],
        text:"When this weapon attacks a target at least half its range away, an unmodified Hit roll of 4+ scores a Critical Hit, instead of the usual 6." },
      { id:"w40k-assault-weapon", title:"Assault (weapon ability)", phase:"Weapon Ability", linkTerm:"Assault", keywords:["assault","assault weapon"],
        text:"A model can shoot this weapon even if its unit Advanced this turn." },
      { id:"w40k-heavy-weapon", title:"Heavy (weapon ability)", phase:"Weapon Ability", linkTerm:"Heavy", keywords:["heavy","heavy weapon"],
        text:"Add 1 to the hit roll for this weapon if the bearer's unit Remained Stationary this turn." },
      { id:"w40k-pistol-weapon", title:"Pistol", phase:"Weapon Ability", linkTerm:"Pistol", keywords:["pistol","pistol weapon"],
        text:"A model can shoot this weapon even while its unit is within Engagement Range of the enemy, targeting only the unit it's fighting." },
      { id:"w40k-battle-round", title:"Battle Round & Phases", phase:"General", linkTerm:"Battle Round", keywords:["battle round","turn order","phases of a turn","game phases","list of phases","how many phases","order of the phases","what are the phases","turn phases","phases are there"],
        text:"Each battle round, both players take a turn made up of the Command, Movement, Shooting, Charge, and Fight phases, in that order." },
      { id:"w40k-command-phase-steps", title:"Command Phase — Full Sequence", phase:"Command", keywords:["command phase","command phase steps","steps in the command phase","steps of the command phase","command phase order","what happens in the command phase"],
        text:"The Command phase has three parts, in order: 1) you gain 1 Command Point; 2) resolve a battle-shock roll for every unit at or below half-strength, or already Battle-shocked (it gets a fresh chance to recover, but doesn't do so automatically); 3) resolve any other Command-phase abilities, Stratagems, or mission rules — these happen after Battle-shock, so anything that returns models to a unit arrives too late to help it pass that test." },
      { id:"w40k-movement-phase-steps", title:"Movement Phase — Full Sequence", phase:"Movement", keywords:["movement phase steps","steps in the movement phase","steps of the movement phase","movement phase order","what happens in the movement phase"],
        text:"At the start of the Movement phase, every unit — including those in Strategic Reserves or embarked in a Transport — becomes eligible to move. One at a time, select a unit and give it a Normal Move, an Advance, a Fall Back, or have it Remain Stationary; a unit in Reserves instead Remains Stationary or makes an Ingress Move to arrive. There's no separate Reinforcements step anymore — reserves can arrive at any point during the phase, not just at the end." },
      { id:"w40k-shooting-phase-steps", title:"Shooting Phase — Full Sequence", phase:"Shooting", keywords:["shooting phase steps","steps in the shooting phase","steps of the shooting phase","shooting phase order","what happens in the shooting phase"],
        text:"One at a time, select an eligible unit — one that didn't Advance or Fall Back this turn, unless an ability says otherwise — and choose one or more valid, visible targets for it. Resolve that unit's attacks completely (hit rolls, wound rolls, saves, damage) before selecting the next unit to shoot." },
      { id:"w40k-charge-phase-steps", title:"Charge Phase — Full Sequence", phase:"Charge", keywords:["charge phase steps","steps in the charge phase","steps of the charge phase","charge phase order","what happens in the charge phase"],
        text:"One at a time, declare a charge with an eligible unit, roll 2D6 for distance, select your targets, and move the unit to end Engaged with all of them. The Charge phase isn't interrupted by shooting — Fire Overwatch only ever triggers at the end of the Movement phase, never during Charges." },
      { id:"w40k-fight-phase-steps", title:"Fight Phase — Full Sequence", phase:"Fight", keywords:["fight phase steps","steps in the fight phase","steps of the fight phase","fight phase order","what happens in the fight phase"],
        text:"Units that charged this turn, and any unit with Fights First, are chosen to fight before everyone else. After that, the active player and their opponent alternate choosing one eligible unit at a time to fight until none remain. Each unit piles in, attacks, then consolidates before the next unit is chosen." },
      { id:"w40k-counter-charge", title:"Counter-charge", phase:"Charge", keywords:["counter charge","counter-charge stratagem"],
        text:"A core Stratagem usable at the end of your opponent's Charge phase, letting you charge back with units that were just charged. For 1 CP, make the charge roll normally with no special cap. For 2 CP, you can instead target anything within 6 inches, but the charge roll itself is capped at 6 inches." },
      { id:"w40k-victory-points", title:"Victory Points & Objectives", phase:"Scoring", linkTerm:"Victory Points", keywords:["victory points","primary objective","secondary objective"],
        text:"Players score Victory Points from Primary and Secondary Objectives set out by the mission; whoever has more at the end of the game wins." },
      { id:"w40k-look-out-sir", title:"Look Out, Sir", phase:"Shooting", linkTerm:"Look Out, Sir", keywords:["look out sir","look out, sir"],
        text:"A Character model within a unit can't be chosen as the target of a ranged attack unless it's the closest eligible target, or the attacking weapon has the Precision ability." },
      { id:"w40k-leader", title:"Leader (attached Characters)", phase:"General", keywords:["leader ability","attach a character","attached unit"],
        text:"A Character with the Leader ability can attach to a compatible Bodyguard unit before the battle. While attached, the Character and unit are treated as a single unit for most rules purposes." },
      { id:"w40k-actions", title:"Actions", phase:"General", keywords:["perform an action","action rule","start an action","actions","action"],
        text:"A unit can start an action if it isn't Battle-shocked, isn't engaged (unless Titanic), has an Objective Control greater than 0, and didn't Advance, Fall Back, or start another action this turn. While performing it, the unit can't shoot (unless Titanic) or declare a charge, and any move other than a pile-in or consolidation fails the action." },
      { id:"w40k-modifier-cap", title:"Hit/Wound Roll Modifiers", phase:"General", keywords:["modifier cap","reroll rules","unmodified roll","roll modifiers","modifiers"],
        text:"Hit and wound rolls can't be modified by more than +1 or -1 in total, however many individual modifiers apply. An unmodified roll of 1 always fails; rerolls are applied before modifiers, and a die can't be rerolled more than once." },
      { id:"w40k-attack-sequence", title:"Attack Sequence — Full Sequence", phase:"General", keywords:["attack sequence steps","hit roll wound roll save roll","how do attacks work","steps of an attack"],
        text:"Resolving an attack always follows four steps: 1) Hit Roll — an unmodified 1 always fails and an unmodified 6 is a Critical Hit, otherwise you need to meet the weapon's BS or WS; 2) Wound Roll — same unmodified 1/6 rule, otherwise compare Strength to Toughness; 3) Save Roll — the defender checks their invulnerable save, then their armour save modified by AP; 4) Inflict Damage — a failed save loses wounds equal to the weapon's Damage characteristic." },
      { id:"w40k-wound-allocation", title:"Wound Allocation & Character Grouping", phase:"General", keywords:["wound allocation","why did the wound go to my character","save roll groups"],
        text:"Before making save rolls, the defender splits their unit into groups — one per Character model, plus one group for all other models sharing the same Wounds, Save, and Invulnerable Save characteristics — and chooses the order attacks are allocated to those groups. A group containing an already-wounded model must come before an undamaged group of the same type, and no Character group can be resolved before every non-Character group has been." },
      { id:"w40k-deadly-demise", title:"Deadly Demise", phase:"General", keywords:["deadly demise"],
        text:"When a model with this ability is destroyed, roll a D6; on the ability's listed threshold, each unit within range suffers mortal wounds." },
      { id:"w40k-stealth", title:"Stealth", phase:"General", keywords:["stealth","stealth ability"],
        text:"Attacks that target a unit with the Stealth ability suffer a -1 penalty to their hit roll." },
      { id:"w40k-scouts", title:"Scouts", phase:"General", keywords:["scout","scouts","scout move","scouts ability"],
        text:"Before the first turn begins, a unit with a Scouts X\" ability can make a free Normal Move of up to X inches, following normal movement restrictions." },
      { id:"w40k-infiltrators", title:"Infiltrators", phase:"General", keywords:["infiltrators","infiltrator","infiltrators ability"],
        text:"A unit with the Infiltrators ability can be set up anywhere on the battlefield more than 9 inches from the enemy deployment zone and all enemy models, instead of deploying normally." },
      { id:"w40k-character-targeting", title:"Character (targeting)", phase:"General", keywords:["character keyword","character targeting"],
        text:"Units with the Character keyword typically can't be given Objective Control unless stated otherwise, and benefit from Look Out, Sir when part of a unit." },
      { id:"w40k-transports", title:"Transports & Fire Points", phase:"General", keywords:["transport capacity","transports","transport"],
        text:"Transport models carry other units around the battlefield. Units can start the battle already embarked, or embark and disembark during the game — see Embark, Disembark, and Firing Deck for the exact conditions. While embarked, a unit isn't on the battlefield and can't be targeted, measured to, or otherwise affected by anything until it disembarks." },
      { id:"w40k-embark", title:"Embark", phase:"Movement", linkTerm:"Embark", keywords:["embark","embarking","embark on transport"],
        text:"A unit can embark within a friendly Transport if every model in it ends a Normal, Advance, or Fall Back move within 3 inches of that Transport, the Transport has enough remaining capacity, and the unit meets any keyword or faction restrictions on the Transport's datasheet. A unit can't embark in the same turn it was set up on the battlefield — that includes a unit that just disembarked, and one that just arrived from Deep Strike or Reserves. Once the conditions are met, the unit is removed from the battlefield as embarked." },
      { id:"w40k-disembark", title:"Disembark", phase:"Movement", linkTerm:"Disembark", keywords:["disembark","disembarking"],
        text:"A unit embarked at the start of your Movement phase can disembark that phase, as long as its Transport hasn't yet made a Normal Move, Advanced, or Fallen Back this phase. Set the disembarking unit up wholly within 3 inches of the Transport and outside Engagement Range of any enemy models. If the Transport already made a Normal Move this phase before it disembarked, the unit counts as having made a Normal Move too — it can't move further and can't charge this turn — but if the Transport Remained Stationary, the unit can move, shoot, charge, and fight completely normally afterward; it just can't itself choose to Remain Stationary, since disembarking already counts as moving." },
      { id:"w40k-firing-deck", title:"Firing Deck", phase:"Shooting", linkTerm:"Firing Deck", keywords:["firing deck","fire deck","fire points"],
        text:"Firing Deck X lets a Transport's embarked passengers shoot without disembarking. When the Transport is selected to shoot, pick up to X embarked models to each fire one of their ranged weapons. For these purposes the Transport itself counts as being equipped with those weapons, so an ability that buffs 'weapons equipped by models in this unit' for the passenger's own unit won't apply to a Firing Deck attack." },
      { id:"w40k-emergency-disembark", title:"Emergency Disembark", phase:"General", relatedTo:"w40k-transports", linkTerm:"Emergency Disembark", keywords:["emergency disembark","transport destroyed","destroyed transport passengers"],
        text:"If a unit's Transport is destroyed, its passengers must immediately disembark — following the normal Disembark rules (wholly within 3 inches, outside Engagement Range) — before the Transport model is removed. They aren't affected by the Transport's own Explodes-type ability; instead, roll one D6 per disembarked model, and for each result of 1 you choose one of those models to be destroyed. A unit that disembarks this way can't declare a charge or perform Heroic Intervention that turn." },
      { id:"w40k-clar-overwatch-timing", title:"Overwatch Covers the Whole Movement Phase", phase:"Clarification", relatedTo:"w40k-overwatch", keywords:["overwatch after fall back","overwatch timing question"],
        text:"Fire Overwatch fires once, at the very end of your opponent's Movement phase — it isn't a separate reactive window per unit that moves. A unit that fell back earlier in that same phase can still be targeted when Overwatch is used at the end of it." },
      { id:"w40k-clar-cover-melee", title:"Cover Doesn't Apply in the Fight Phase", phase:"Clarification", relatedTo:"w40k-cover", keywords:["cover in melee","does cover work in combat"],
        text:"The Benefit of Cover only worsens the Ballistic Skill of ranged attacks against the unit. It has no effect at all on melee attacks made in the Fight phase." },
      { id:"w40k-clar-charge-los", title:"Charging Doesn't Require Line of Sight", phase:"Clarification", relatedTo:"w40k-charge", keywords:["charge without line of sight","can i charge if i can't see"],
        text:"Unlike shooting, declaring a charge doesn't require the target to be visible — only that it's within 12 inches and otherwise a legal target. You can charge a unit you can't currently see." },
      { id:"w40k-clar-battleshock-scope", title:"What Battle-shock Actually Stops You Doing", phase:"Clarification", relatedTo:"w40k-battle-shock", keywords:["can battle-shocked units shoot","what does battle-shock stop"],
        text:"A Battle-shocked unit can still move, shoot, charge, and fight normally. The only effects are: its Objective Control drops to '-', it can't be targeted by Stratagems, and it can't start actions — it isn't locked out of the game the way some players assume." },
      { id:"w40k-clar-split-fire", title:"A Unit's Shooting Targets One Unit by Default", phase:"Clarification", relatedTo:"w40k-shoot", keywords:["split fire","can different models in a unit target different enemies"],
        text:"By default, all of a unit's shooting attacks in one activation are resolved against a single chosen target — models can't split fire onto different enemy units unless a specific rule or ability explicitly grants that." },
      { id:"w40k-clar-overwatch-vs-charge", title:"Overwatch Can't Target a Charging Unit", phase:"Clarification", relatedTo:"w40k-overwatch", keywords:["overwatch that charge","overwatch a charge","overwatch the charge","overwatch charging unit","can i overwatch a charge"],
        text:"Fire Overwatch only responds to your opponent's Movement phase, resolving once at its end. Because Charges happen in a separate, later phase, Overwatch has already been used or passed on by the time a charge is declared — it can no longer be fired at a charging unit the way it could in 10th edition." },
      { id:"w40k-clar-embarked-cant-overwatch", title:"Embarked Units Can't Fire Overwatch", phase:"Clarification", relatedTo:"w40k-overwatch", keywords:["overwatch from transport","embarked unit shoot"],
        text:"A unit embarked inside a Transport isn't on the battlefield and can't shoot at all — including firing Fire Overwatch — unless it's doing so through the Transport's Fire Points." },
      { id:"w40k-clar-battleshock-recovers", title:"Battle-shock Is Re-tested Every Command Phase", phase:"Clarification", relatedTo:"w40k-battle-shock", keywords:["recover from battle-shock","does battle-shock last forever"],
        text:"Battle-shock isn't permanent. A fresh battle-shock roll is made for the unit at the start of every Command phase, so a unit that failed last turn can pass and fully recover the very next one." },
      { id:"w40k-clar-charge-survives-overwatch", title:"A Charge Still Goes Ahead After Overwatch Casualties", phase:"Clarification", relatedTo:"w40k-charge", keywords:["charge after overwatch","overwatch stops charge"],
        text:"Taking casualties from Overwatch doesn't cancel a charge outright — as long as enough models remain to declare and complete it, the charge still goes ahead in the Charge phase as normal." },
      { id:"w40k-clar-look-out-sir-scope", title:"Look Out, Sir Needs Non-Character Models Present", phase:"Clarification", relatedTo:"w40k-look-out-sir", keywords:["look out sir lone character","does look out sir work alone"],
        text:"Look Out, Sir only protects a Character while it's part of a unit that also contains non-Character models. A lone Character, or a unit made up entirely of Characters, gets no such protection and can be targeted normally." },
      { id:"w40k-clar-character-precision", title:"Character vs. Character Fights Get Precision", phase:"Clarification", relatedTo:"w40k-precision", keywords:["character fighting character","precision character vs character"],
        text:"When a Character model fights an enemy Character in the Fight phase, its melee attacks automatically gain the Precision ability for that fight, even if its weapon doesn't normally have it." },

      // ---- Movement (10) ----
      { id:"w40k-clar-advance-no-charge", title:"Advancing Rules Out Charging This Turn", phase:"Clarification", relatedTo:"w40k-advance", keywords:["can i charge after advancing","advance and charge same turn","advancing then charging"],
        text:"Advance locks out shooting and charging for the rest of that turn unless a specific ability overrides it — a unit that Advances can't declare a charge later in the same turn." },
      { id:"w40k-clar-fallback-no-shoot-charge", title:"Falling Back Locks Out Shooting and Charging", phase:"Clarification", relatedTo:"w40k-fallback", keywords:["can i shoot after falling back","fall back then charge","fall back then shoot"],
        text:"A unit that Falls Back — whether voluntarily or via a forced Desperate Escape — can't shoot or charge that turn unless a specific ability says otherwise." },
      { id:"w40k-clar-move-through-enemy", title:"Units Can't Move Through Enemy Models", phase:"Clarification", relatedTo:"w40k-move", keywords:["can i move through enemy models","moving through the enemy","move over enemy models"],
        text:"Free movement through other models only covers friendly ones. A Normal Move, Advance, or Fall Back can't pass a model through enemy models unless an ability — like Desperate Escape — explicitly grants that." },
      { id:"w40k-clar-rotate-free", title:"Rotating a Model Doesn't Use Up Its Move", phase:"Clarification", relatedTo:"w40k-move", keywords:["does turning cost movement","can i rotate for free","pivoting a model"],
        text:"Turning a model on the spot, without otherwise repositioning it, costs no movement at all — you can rotate freely before, during, or after using the rest of its Move." },
      { id:"w40k-clar-difficult-terrain-check", title:"There's No Single Universal Difficult Terrain Penalty", phase:"Clarification", relatedTo:"w40k-difficult-terrain", keywords:["is there a difficult terrain rule","universal difficult terrain penalty"],
        text:"11th edition has no blanket 'difficult terrain' rule — what actually happens is set by each feature's own traits (Exposed, Light, or Dense), together with Cover and Hidden, so always check the specific terrain piece." },
      { id:"w40k-clar-deep-strike-not-universal", title:"Deep Strike Isn't a Standalone Move Type Anymore", phase:"Clarification", relatedTo:"w40k-deep-strike", keywords:["is deep strike still a rule","does deep strike exist in 11th edition","universal deep strike"],
        text:"You won't find Deep Strike in the core list of move types in 11th edition. Where a unit still has it, it's a datasheet ability that loosens the normal Ingress Move restrictions — check that unit's own wording rather than assuming a universal rule applies." },
      { id:"w40k-clar-reserves-half-points", title:"How Much of an Army Can Sit in Strategic Reserves", phase:"Clarification", relatedTo:"w40k-strategic-reserves", keywords:["how many points can i put in reserve","reserves points limit","strategic reserves cap"],
        text:"The cap on Strategic Reserves is a points limit, not a model or unit count — roughly half your total army's points value can be held back at list-building time." },
      { id:"w40k-clar-ingress-no-other-move", title:"A Unit That Arrives by Ingress Move Can't Also Advance or Fall Back That Phase", phase:"Clarification", relatedTo:"w40k-ingress-move", keywords:["can i advance after arriving from reserves","ingress move and advance","arrive from reserves then move again"],
        text:"Making an Ingress Move uses up that unit's move for the phase — it can't then also Advance or Fall Back, since arriving is the only movement action it performs that Movement phase." },
      { id:"w40k-clar-reserves-no-turn-one", title:"Reserves Can't Arrive in Battle Round One", phase:"Clarification", relatedTo:"w40k-strategic-reserves", keywords:["can reserves arrive turn 1","first turn deep strike","reserves battle round 1"],
        text:"Units in Strategic Reserves can't make an Ingress Move before the second battle round, even though the phase itself has no separate Reinforcements step to wait for — the round restriction still applies." },
      { id:"w40k-clar-embark-no-separate-move", title:"Embarking Doesn't Require Its Own Dedicated Move", phase:"Clarification", relatedTo:"w40k-embark", keywords:["do i need a separate move to embark","embarking during a normal move","embark as part of moving"],
        text:"A unit doesn't need a special move just to embark — ending a Normal Move, Advance, or Fall Back within 3 inches of the Transport (with capacity and restrictions met) is enough, so embarking happens as the natural endpoint of a move it's already making." },

      // ---- Shooting (15) ----
      { id:"w40k-clar-cover-hit-not-save", title:"Cover Worsens the Attacker's Hit Roll, Not the Defender's Save", phase:"Clarification", relatedTo:"w40k-cover", keywords:["does cover add to my save","how does cover work now","cover to hit or save"],
        text:"Cover doesn't boost the target's armour save the way some past editions did — it applies a flat -1 to the attacker's Ballistic Skill for that shooting attack instead." },
      { id:"w40k-clar-shoot-advance-restriction", title:"You Can't Normal-Shoot After Advancing", phase:"Clarification", relatedTo:"w40k-shooting-types", keywords:["can i shoot after advancing","shooting after advance","advance and shoot"],
        text:"Normal Shooting requires a unit that didn't Advance this turn. A unit that Advanced can only shoot via Assault Shooting, and only if it has weapons with the Assault ability." },
      { id:"w40k-clar-close-quarters-vehicle-penalty", title:"A Vehicle or Monster's Non-Close-Quarters Weapons Are Penalized in Combat", phase:"Clarification", relatedTo:"w40k-shooting-types", keywords:["can my tank shoot in melee","vehicle shooting while engaged","monster shooting in combat"],
        text:"Any Monster or Vehicle can use Close-Quarters Shooting even without a dedicated Close-Quarters weapon, but any weapon it fires this way that doesn't actually have the Close-Quarters ability suffers a -1 penalty to hit." },
      { id:"w40k-clar-indirect-needs-6-or-stationary", title:"Indirect Fire's To-Hit Depends on Whether You Moved", phase:"Clarification", relatedTo:"w40k-shooting-types", keywords:["indirect fire hit roll","indirect shooting to hit","indirect fire 4+"],
        text:"Indirect Shooting normally needs an unmodified 6 to hit with no rerolls. That threshold only drops to a 4+ if the firing unit Remained Stationary this turn and the target is visible to another friendly unit." },
      { id:"w40k-clar-los-partial-visible", title:"Any Visible Part of a Model Is Enough for Line of Sight", phase:"Clarification", relatedTo:"w40k-line-of-sight", keywords:["do i need to see the whole model","partial visibility line of sight","how much of a model must be visible"],
        text:"You don't need to see a model's whole body to draw line of sight to it — seeing any part of it from the shooting model's location is enough, subject to Hidden overriding visibility for qualifying models." },
      { id:"w40k-clar-hidden-detection-range", title:"Hidden Only Blocks Targeting Beyond Its Detection Range", phase:"Clarification", relatedTo:"w40k-hidden", keywords:["can hidden units still be shot","hidden range limit","hidden status still targetable"],
        text:"Hidden doesn't make a model untargetable outright — enemy models more than the stated distance away (15 inches normally, 12 for Gone to Ground) can't target it, but a closer enemy still can." },
      { id:"w40k-clar-hidden-breaks-on-shooting", title:"Shooting Removes Hidden and Gone to Ground", phase:"Clarification", relatedTo:"w40k-hidden", keywords:["does shooting remove hidden status","hidden status lost after shooting","gone to ground after shooting"],
        text:"Hidden and Gone to Ground both require the unit to have made no ranged attacks this turn or last turn. The moment that unit shoots, it loses the status until enough turns pass without firing again." },
      { id:"w40k-clar-obscuring-vs-cover", title:"Obscuring and Cover Are Separate Checks", phase:"Clarification", relatedTo:"w40k-obscuring", keywords:["difference between obscuring and cover","obscuring vs cover"],
        text:"Obscuring terrain can remove line of sight entirely between two models outside it — a different question from whether a visible target gets the Benefit of Cover. An attack can be blocked by Obscuring before Cover even becomes relevant." },
      { id:"w40k-clar-solid-small-gaps", title:"Small Gaps in Dense Terrain Still Block Line of Sight", phase:"Clarification", relatedTo:"w40k-solid", keywords:["can i see through a window in a ruin","small gaps in terrain","shoot through a doorway"],
        text:"The Solid rule blocks line of sight through any enclosed opening in Dense terrain — a window, doorway, or small hole — if it's 3 inches or less above ground level, regardless of how large the opening looks." },
      { id:"w40k-clar-blast-engagement-restriction", title:"Blast Weapons Can't Target Units You're Already Fighting", phase:"Clarification", relatedTo:"w40k-blast", keywords:["can i blast a unit in combat","blast into melee","blast weapon engagement range"],
        text:"A Blast weapon can't be used to shoot a unit that's within Engagement Range of any of your own units, even if the firing model itself isn't the one engaged, to avoid catching your own troops in the explosion." },
      { id:"w40k-clar-rapid-fire-half-range", title:"Rapid Fire Only Adds Attacks Within Half Range", phase:"Clarification", relatedTo:"w40k-rapid-fire", keywords:["rapid fire range requirement","when does rapid fire apply","rapid fire half range"],
        text:"The bonus attacks from Rapid Fire X only apply if the target is within half the weapon's printed range — beyond that distance the weapon just makes its normal number of attacks." },
      { id:"w40k-clar-sustained-vs-lethal", title:"Sustained Hits and Lethal Hits Both Trigger on Critical Hits", phase:"Clarification", relatedTo:"w40k-sustained-hits", keywords:["sustained hits and lethal hits together","difference between sustained and lethal hits"],
        text:"Both abilities key off the same trigger — an unmodified 6 to hit — but do different things: Sustained Hits adds extra automatic hits, while Lethal Hits skips the wound roll. A weapon can have both, applying both effects to the same Critical Hit." },
      { id:"w40k-clar-devastating-vs-lethal", title:"Devastating Wounds Triggers on the Wound Roll, Not the Hit Roll", phase:"Clarification", relatedTo:"w40k-devastating-wounds", keywords:["when does devastating wounds trigger","devastating wounds vs lethal hits"],
        text:"Devastating Wounds keys off a Critical Wound — an unmodified 6 on the wound roll — not the hit roll, making it a separate trigger from Lethal Hits or Sustained Hits, which both key off Critical Hits." },
      { id:"w40k-clar-lethal-hits-skip-wound", title:"Lethal Hits Skip the Wound Roll, Not the Save", phase:"Clarification", relatedTo:"w40k-lethal-hits", keywords:["does lethal hits skip the save","lethal hits armour save"],
        text:"A Lethal Hits critical hit auto-wounds, but the attack still goes on to a normal save roll and damage — it isn't a mortal wound, unlike Devastating Wounds, so normal saves still apply." },
      { id:"w40k-clar-anti-x-still-needs-hit", title:"Anti-X Still Requires a Successful Hit Roll First", phase:"Clarification", relatedTo:"w40k-anti-x", keywords:["does anti-x skip the hit roll","anti-tank auto wound","anti-infantry auto wound"],
        text:"Anti-[Keyword] X+ only changes what a wound roll of X or more does against that keyword — it doesn't bypass the hit roll, which still has to succeed normally first." },
      { id:"w40k-clar-restricted-ability-variant", title:"Some Abilities Are Printed with a Built-In Target Restriction", phase:"Clarification", relatedTo:"w40k-lethal-hits", keywords:["lethal hits non-monster/vehicle meaning","devastating wounds infantry meaning","what does the colon mean on an ability","ability restricted to a keyword","non-monster/vehicle ability"],
        text:"A datasheet can print a normally-universal ability with its own built-in exception, shown as a colon plus a keyword — for example Lethal Hits: non-MONSTER/VEHICLE, Devastating Wounds: INFANTRY, or Sustained Hits 2: MONSTER/VEHICLE. The ability works exactly like its unrestricted version, except it only applies when the target does (or, for a 'non-' qualifier, doesn't) have the named keyword — check the specific unit's printed wording rather than assuming the plain version of the ability applies." },

      // ---- Charge (10) ----
      { id:"w40k-clar-charge-must-be-unengaged", title:"You Must Be Unengaged to Declare a Charge", phase:"Clarification", relatedTo:"w40k-charge", keywords:["can an engaged unit charge","charge while already in combat"],
        text:"A unit already within Engagement Range of the enemy can't declare a new charge — charging closes the distance to the enemy, it isn't available to units already locked in combat." },
      { id:"w40k-clar-charge-target-in-range", title:"Every Charge Target Must Be Within 12 Inches and Within the Roll", phase:"Clarification", relatedTo:"w40k-charge", keywords:["can i charge two units","multi-charge distance requirement"],
        text:"You choose your charge targets after rolling 2D6, but each one must be within both the 12-inch declaration range and the actual distance rolled — you can't tag a farther unit onto a closer, successful charge." },
      { id:"w40k-clar-charge-move-engages-all", title:"A Charge Move Must End Engaged with Every Declared Target", phase:"Clarification", relatedTo:"w40k-charge", keywords:["do i have to engage every charged unit","multi charge move requirements"],
        text:"If you declare a charge against multiple enemy units, the charging unit's move has to end within Engagement Range of all of them — if it can't reach every declared target, the charge fails." },
      { id:"w40k-clar-heroic-intervention-walker-only", title:"Only Walker Vehicles Can Heroic Intervene", phase:"Clarification", relatedTo:"w40k-heroic-intervention", keywords:["can my tank use heroic intervention","vehicle heroic intervention"],
        text:"Heroic Intervention is open to any eligible unit except Vehicles that aren't Walkers — a non-Walker tank can't use this Stratagem even if it would otherwise qualify." },
      { id:"w40k-clar-heroic-intervention-no-fights-first", title:"Heroic Intervention Never Grants Fights First", phase:"Clarification", relatedTo:"w40k-heroic-intervention", keywords:["does heroic intervention give fights first","heroic intervention charge bonus"],
        text:"Even a successful Heroic Intervention charge doesn't give the unit Fights First — that bonus only comes from charging in your own Charge phase, not from this reactive Stratagem." },
      { id:"w40k-clar-crushing-impact-self-harm", title:"Crushing Impact Can Hurt Your Own Unit", phase:"Clarification", relatedTo:"w40k-crushing-impact", keywords:["can crushing impact hurt my own unit","tank shock backfire"],
        text:"Rolling a 1 on any Crushing Impact die inflicts a mortal wound on your own Monster or Vehicle, even while the same Stratagem is damaging the enemy — it's a genuine risk, not a free attack." },
      { id:"w40k-clar-counter-charge-two-costs", title:"Counter-charge Has Two Different Cost Tiers", phase:"Clarification", relatedTo:"w40k-counter-charge", keywords:["counter-charge cost options","counter charge 1cp vs 2cp"],
        text:"For 1 CP, Counter-charge only lets you charge back the specific units that just charged you, with no roll cap. For 2 CP, you can target any unit within 6 inches instead, but that version caps your charge roll at 6 inches." },
      { id:"w40k-clar-hooked-charge-bonus", title:"Hooked Grants a Charge Bonus, Not an Automatic Hit", phase:"Clarification", relatedTo:"w40k-hooked", keywords:["how does hooked work","hooked weapon charge bonus"],
        text:"Hooked only triggers off a successful hit against a Monster or Vehicle — it then boosts the charge roll against that target and denies it Overwatch, but doesn't otherwise change the attack that triggered it." },
      { id:"w40k-clar-harpooned-forces-engage", title:"Harpooned Requires You to Actually Reach the Target", phase:"Clarification", relatedTo:"w40k-harpooned", keywords:["harpooned charge requirement","harpooned vs hooked"],
        text:"Unlike Hooked, a successful Harpooned hit doesn't just grant a charge bonus — the following charge move must actually end engaged with that specific target, not merely attempt to reach it." },
      { id:"w40k-clar-charge-declared-before-move", title:"You Declare a Charge, Then Roll, Then Choose the Move", phase:"Clarification", relatedTo:"w40k-charge", keywords:["charge sequence order","do i roll before or after declaring a charge"],
        text:"Declaring the charge and picking targets comes first, then you roll 2D6 for distance, and only then do you actually move the unit — you already know your distance before deciding exactly how to end the move." },

      // ---- Fight (15) ----
      { id:"w40k-clar-fights-first-priority-order", title:"Fights First Units Go Before Everyone Else", phase:"Clarification", relatedTo:"w40k-fights-first", keywords:["fight order with multiple fights first units","who chooses fights first order"],
        text:"Every unit with Fights First — whether from charging or from an ability — is selected to fight before any non-Fights-First unit, with the two players still alternating choices among their own Fights First units first." },
      { id:"w40k-clar-pile-in-toward-closest", title:"Pile In Must Move a Model Closer to the Nearest Enemy", phase:"Clarification", relatedTo:"w40k-pile-in", keywords:["pile in restrictions","can i pile in any direction"],
        text:"A pile-in move isn't a free 3-inch repositioning — each model has to end closer to the closest enemy model than it started, and a model already in base contact with an enemy can't pile in at all." },
      { id:"w40k-clar-consolidate-order-mandatory", title:"Consolidation Modes Are Checked in a Fixed Order", phase:"Clarification", relatedTo:"w40k-consolidate", keywords:["can i choose which consolidation to use","consolidation order rules"],
        text:"You don't freely pick between Ongoing, Engaging, and Objective consolidation — they're checked in that order, and whichever applies first is mandatory; you can't choose Objective consolidation if Engaging still applies." },
      { id:"w40k-clar-consolidate-ongoing-vs-engaging", title:"Ongoing and Engaging Consolidation Aren't the Same Thing", phase:"Clarification", relatedTo:"w40k-consolidate", keywords:["ongoing vs engaging consolidation","difference between consolidation types"],
        text:"Ongoing Consolidation only applies if the unit is still engaged after fighting; Engaging Consolidation is the separate case where it's unengaged but within 3 inches of an enemy it can move to engage. Only one of them can apply to a given unit." },
      { id:"w40k-clar-overrun-only-if-unengaged", title:"Overrun Fight Only Applies to a Unit With No One Left to Fight", phase:"Clarification", relatedTo:"w40k-overrun-fight", keywords:["when does overrun fight trigger","overrun fight conditions"],
        text:"A unit still engaged with a living enemy just fights normally — Overrun Fight only kicks in for a unit eligible to fight but with nothing left in Engagement Range, most often because it wiped out everything it was fighting earlier that phase." },
      { id:"w40k-clar-overrun-extra-pile-in-range", title:"Overrun Fight's Extra Pile-In Can Reach Farther Than Normal", phase:"Clarification", relatedTo:"w40k-overrun-fight", keywords:["overrun fight range","overrun fight 5 inches"],
        text:"A normal pile-in only moves toward the closest enemy within reach, but an Overrun Fight's extra pile-in can target enemy units up to 5 inches away, since the unit doesn't already have an adjacent enemy to close on." },
      { id:"w40k-clar-engagement-range-both-axes", title:"Engagement Range Has Both a Horizontal and Vertical Limit", phase:"Clarification", relatedTo:"w40k-engagement-range", keywords:["engagement range vertical distance","engagement range on different levels"],
        text:"A model isn't within Engagement Range just because it's horizontally close — it has to be within 2 inches horizontally and 5 inches vertically at the same time, so a model on a much higher or lower level can be out of range even at short horizontal distance." },
      { id:"w40k-clar-feel-no-pain-per-point", title:"Feel No Pain Is Rolled Separately for Each Point of Damage", phase:"Clarification", relatedTo:"w40k-feel-no-pain", keywords:["how many dice do i roll for feel no pain","feel no pain per wound"],
        text:"Feel No Pain doesn't make one roll for the whole attack — you roll a D6 for every individual point of damage the model is about to lose, and each point is ignored independently on a result meeting the threshold." },
      { id:"w40k-clar-precision-still-needs-hit", title:"Precision Still Requires a Successful Hit and Wound", phase:"Clarification", relatedTo:"w40k-precision", keywords:["does precision skip the hit roll","precision weapon requirements"],
        text:"Precision only changes which model in the target unit an attack is allocated to after it wounds — it doesn't skip the hit roll, wound roll, or the target's saves." },
      { id:"w40k-clar-precision-bypasses-lookout-sir", title:"Precision Bypasses Look Out, Sir's Ranged Protection", phase:"Clarification", relatedTo:"w40k-look-out-sir", keywords:["does precision ignore look out sir","precision weapon vs look out sir"],
        text:"A weapon with Precision can target a protected Character directly, ignoring Look Out, Sir's usual requirement that a ranged attack hit the closest eligible model first." },
      { id:"w40k-clar-wound-allocation-character-last", title:"Character Groups Are Wounded Last Among Undamaged Groups", phase:"Clarification", relatedTo:"w40k-wound-allocation", keywords:["can characters be wounded first","wound allocation character order"],
        text:"Attacks can't be sent into a Character's wound-allocation group before every non-Character group in the unit has been allocated to, unless that Character group already contains a wounded model." },
      { id:"w40k-clar-attached-unit-highest-stat", title:"Attached Units Use the Highest Value Among Their Models", phase:"Clarification", relatedTo:"w40k-attached-units", keywords:["attached unit toughness","leader changes unit toughness"],
        text:"When a Leader's characteristic differs from its Bodyguard unit's — Toughness being the classic example — the whole Attached unit uses whichever value is highest among the models actually present, not the Bodyguard's base stat alone." },
      { id:"w40k-clar-lone-operative-melee-unaffected", title:"Lone Operative Doesn't Protect Against Melee Targeting", phase:"Clarification", relatedTo:"w40k-lone-operative", keywords:["does lone operative work in melee","lone operative fight phase"],
        text:"Lone Operative only restricts who can target the model with a ranged attack — it offers no protection at all against being targeted or fought in the Fight phase." },
      { id:"w40k-clar-fights-first-no-stacking", title:"Fights First Doesn't Stack", phase:"Clarification", relatedTo:"w40k-fights-first", keywords:["does fights first stack","multiple fights first sources"],
        text:"A unit either has Fights First or it doesn't for that turn — having multiple sources of it (say, a charge plus an ability) doesn't let it fight twice or grant any benefit beyond going before non-Fights-First units." },
      { id:"w40k-clar-epic-challenge-timing", title:"Epic Challenge Is Used Right After the Unit Is Selected to Fight", phase:"Clarification", relatedTo:"w40k-epic-challenge", keywords:["when to use epic challenge","epic challenge timing"],
        text:"You call Epic Challenge the moment your Character unit is chosen to fight, before pile-in and attacks — the Precision it grants then applies to that unit's attacks for the rest of the phase." },

      // ---- Command / Battle-shock (8) ----
      { id:"w40k-clar-battleshock-half-strength-trigger", title:"Battle-shock Tests Are Triggered by Model Count, Not Wounds Remaining", phase:"Clarification", relatedTo:"w40k-battle-shock", keywords:["what triggers battle-shock","half strength battle-shock"],
        text:"A unit tests for Battle-shock when it's at or below half its starting number of models, not based on how many individual wounds it's lost — a unit of tough single models trickling down in wounds doesn't test for that reason alone." },
      { id:"w40k-clar-battleshock-leadership-target", title:"Passing Battle-shock Needs 2D6 Equal to or Above Leadership", phase:"Clarification", relatedTo:"w40k-battle-shock", keywords:["battle-shock roll target number","how to pass battle-shock"],
        text:"The Battle-shock roll is 2D6 versus the unit's Leadership characteristic — meeting or beating that number avoids or recovers from Battle-shock, while rolling below it fails the test." },
      { id:"w40k-clar-command-point-timing", title:"You Gain Your Command Point Before Battle-shock Tests", phase:"Clarification", relatedTo:"w40k-command-phase-steps", keywords:["do i get cp before battle-shock","command point timing"],
        text:"The Command phase's fixed order means you gain 1 Command Point in step one, before any Battle-shock rolls in step two — so it's available if you want to spend it reactively later, though it can't affect that test itself." },
      { id:"w40k-clar-cp-cant-help-battleshock-retroactively", title:"Command-Phase Abilities Can't Retroactively Save a Unit From Battle-shock", phase:"Clarification", relatedTo:"w40k-command-phase-steps", keywords:["can i heal before battle-shock test","command phase ability order battle-shock"],
        text:"Because Battle-shock resolves in step two, before other Command-phase Stratagems and abilities in step three, nothing you do afterward — like returning models to the unit — can change whether it had to test or how that test went." },
      { id:"w40k-clar-stratagem-once-per-phase", title:"The Same Stratagem Can't Be Used Twice in One Phase by the Same Player", phase:"Clarification", relatedTo:"w40k-command-points", keywords:["can i use the same stratagem twice","stratagem once per phase limit"],
        text:"Each named Stratagem has a once-per-phase limit for its user — you can't spend CP to use the identical Stratagem again that phase, even with CP to spare, though your opponent using it too is unaffected by your usage." },
      { id:"w40k-clar-stratagem-one-per-unit-per-phase", title:"A Unit Can't Be Hit by Two Different Stratagems in the Same Phase", phase:"Clarification", relatedTo:"w40k-command-points", keywords:["can i stack two stratagems on one unit","one stratagem per unit per phase"],
        text:"Unless a Stratagem specifically says otherwise, a single unit can only be the target of one Stratagem per phase, so you can't stack two separate unit-targeted Stratagems onto the same unit in the same phase." },
      { id:"w40k-clar-insane-bravery-once-per-battle", title:"Insane Bravery Can Only Be Used Once, Ever", phase:"Clarification", relatedTo:"w40k-insane-bravery", keywords:["how many times can i use insane bravery","insane bravery once per game"],
        text:"Insane Bravery is stricter than the normal once-per-phase Stratagem limit — you can only use it a single time across the entire battle, on any one Battle-shock test you choose." },
      { id:"w40k-clar-command-reroll-single-roll", title:"Command Re-Roll Only Affects One Roll or Test", phase:"Clarification", relatedTo:"w40k-command-reroll", keywords:["what can command re-roll affect","command reroll single die"],
        text:"Command Re-Roll re-rolls exactly one Advance, Charge, Hit, Wound, Damage, or Attacks-count roll, one Desperate Escape test, one Hazard roll, or one saving throw — not every die in a batch of attacks." },

      // ---- Objectives / Scoring (10) ----
      { id:"w40k-clar-oc-tie-uncontrolled", title:"A Tied Objective Control Total Leaves the Objective Uncontrolled", phase:"Clarification", relatedTo:"w40k-objective-control", keywords:["what happens on a tied objective","equal objective control"],
        text:"If both players have equal Objective Control on a terrain area, neither side controls it — unless one player already had it Secured, in which case a tie isn't enough for the opponent to take it away." },
      { id:"w40k-clar-secured-persists", title:"A Secured Objective Stays Yours Even If You Leave It", phase:"Clarification", relatedTo:"w40k-objective-control", keywords:["do i lose a secured objective if i leave","secured objective control"],
        text:"Once an objective is Secured, moving your models off it doesn't hand it back — your opponent has to get a higher Objective Control total there than you currently have before control actually changes hands." },
      { id:"w40k-clar-battleshocked-oc-zero", title:"A Battle-shocked Unit Contributes No Objective Control at All", phase:"Clarification", relatedTo:"w40k-battle-shock", keywords:["does battle-shock remove objective control completely","battle-shocked unit scoring"],
        text:"Battle-shock doesn't just reduce Objective Control — it sets it to '-', meaning that unit contributes nothing to any objective total while Battle-shocked, even if its printed OC value is high." },
      { id:"w40k-clar-scoring-timing", title:"Most Missions Score at the Start of Your Command Phase", phase:"Clarification", relatedTo:"w40k-victory-points", keywords:["when do i score primary objectives","primary objective scoring timing"],
        text:"Primary Objective scoring is usually a snapshot check taken at the very start of your Command phase, based on whatever your Objective Control totals are at that instant, not a running tally kept throughout the round." },
      { id:"w40k-clar-secondary-separate-from-primary", title:"Secondary Objectives Are Scored Independently of Primaries", phase:"Clarification", relatedTo:"w40k-victory-points", keywords:["are secondaries separate from primaries","secondary objective scoring rules"],
        text:"Secondary Objectives come from their own deck or fixed list and are scored on their own conditions — succeeding or failing at Primary Objectives that turn has no direct bearing on whether a Secondary is achieved." },
      { id:"w40k-clar-draw-possible", title:"Games Can End in a Draw", phase:"Clarification", relatedTo:"w40k-victory-points", keywords:["can a 40k game end in a tie","warhammer draw result"],
        text:"If both players finish the mission with exactly the same total Victory Points, the result is a tied game — there's no automatic tiebreaker built into the base scoring rules." },
      { id:"w40k-clar-battle-rounds-five", title:"Missions Typically Run Five Battle Rounds", phase:"Clarification", relatedTo:"w40k-victory-points", keywords:["how many rounds in a 40k game","how long does a mission last"],
        text:"Standard missions are structured around five battle rounds; scoring happens throughout, but the game and its final tally conclude after the fifth round unless the specific mission says otherwise." },
      { id:"w40k-clar-detachment-mixing", title:"Detachment Points Let You Mix Rules From Multiple Detachments", phase:"Clarification", relatedTo:"w40k-detachments", keywords:["can i use two detachments","combining detachments in one army"],
        text:"You aren't locked into a single Detachment's Stratagems and Enhancements for your whole army — as long as you stay inside your overall Detachment Points budget, you can combine pieces of several different Detachments in one list." },
      { id:"w40k-clar-actions-need-oc", title:"Starting an Action Requires Objective Control Above Zero", phase:"Clarification", relatedTo:"w40k-actions", keywords:["can a unit with no oc do actions","objective control zero and actions"],
        text:"A unit with an Objective Control of 0 — including one reduced to that by an ability like Battle-shock — can't start an action, on top of needing to not be Battle-shocked or already engaged." },
      { id:"w40k-clar-actions-fail-on-move", title:"Almost Any Extra Move Fails an Action in Progress", phase:"Clarification", relatedTo:"w40k-actions", keywords:["what breaks an action","actions and movement interruption"],
        text:"Once a unit is performing an action, any move other than a pile-in or a consolidation immediately fails it — Falling Back, Advancing, or even making a Normal Move all lose the progress on that action." },

      // ---- Terrain / Cover (8) ----
      { id:"w40k-clar-cover-two-qualifying-paths", title:"There Are Two Separate Ways to Get the Benefit of Cover", phase:"Clarification", relatedTo:"w40k-cover", keywords:["two ways to get cover","how do i qualify for cover"],
        text:"A unit gets Cover either because every model in it is Infantry, Beast, or Swarm and it's within a terrain area, or because the target simply isn't fully visible to the attacker due to intervening terrain — either path qualifies independently." },
      { id:"w40k-clar-cover-mixed-keyword-unit", title:"A Mixed-Keyword Unit Can Still Get Cover the Second Way", phase:"Clarification", relatedTo:"w40k-cover", keywords:["mixed unit cover","unit with different keywords cover"],
        text:"If a unit isn't made up entirely of Infantry, Beast, or Swarm models, it can't use the terrain-area path to Cover — but it can still gain Cover normally by being obscured from the attacker's line of sight through intervening terrain." },
      { id:"w40k-clar-terrain-categories", title:"Terrain Features Fall Into Three Fixed Categories", phase:"Clarification", relatedTo:"w40k-terrain-traits", keywords:["what are the terrain categories","exposed light dense terrain"],
        text:"Every terrain feature in 11th edition is Exposed, Light, or Dense, and each category comes with its own fixed movement and visibility rules — this replaces the old Light Cover/Heavy Cover/Obscuring split from 10th edition." },
      { id:"w40k-clar-dense-terrain-movement-height", title:"Dense Terrain Over 2 Inches Tall Requires Climbing for Most Models", phase:"Clarification", relatedTo:"w40k-terrain-movement", keywords:["climbing terrain rules","which models can move through walls"],
        text:"Infantry, Beast, Swarm, and Mobile models can pass horizontally through Dense terrain regardless of height, but any other model has to climb vertically over a Dense section taller than 2 inches, and still can't pass through floors or ceilings while doing so." },
      { id:"w40k-clar-plunging-fire-two-conditions", title:"Plunging Fire Has Two Separate Ways to Qualify", phase:"Clarification", relatedTo:"w40k-plunging-fire", keywords:["how to get plunging fire","plunging fire conditions"],
        text:"You get the +1 Ballistic Skill from Plunging Fire either by shooting from a terrain feature at least 3 inches tall, or by having the Towering keyword and being within 12 inches of the target — either condition alone is enough, as long as the target has a model at ground level." },
      { id:"w40k-clar-obscuring-mutual-blocking", title:"Obscuring Terrain Blocks Sight in Both Directions", phase:"Clarification", relatedTo:"w40k-obscuring", keywords:["does obscuring block sight both ways","obscuring terrain mutual"],
        text:"If Obscuring terrain breaks line of sight between two models, neither one can see the other — it's a mutual effect, not something that only stops the attacker from seeing the target." },
      { id:"w40k-clar-terrain-inside-doesnt-block-own-sight", title:"Standing Inside Obscuring Terrain Doesn't Block Your Own Sight Out of It", phase:"Clarification", relatedTo:"w40k-obscuring", keywords:["can i see out of terrain im standing in","obscuring terrain from inside"],
        text:"The Obscuring rule only applies when line of sight crosses a terrain area that neither model is standing inside — a model actually inside that feature isn't blocked from seeing, or being seen by, targets outside it purely by that same feature." },
      { id:"w40k-clar-gone-to-ground-needs-dense", title:"Gone to Ground Specifically Needs Dense Terrain", phase:"Clarification", relatedTo:"w40k-gone-to-ground", keywords:["gone to ground light terrain","does gone to ground work in light terrain"],
        text:"Being Hidden inside Light terrain isn't enough for Gone to Ground — the extra step down to a 12-inch detection range only applies when the model's lack of visibility is specifically due to a Dense terrain feature." },

      // ---- Transports (8) ----
      { id:"w40k-clar-embarked-cant-be-affected", title:"Embarked Units Are Completely Outside the Game Until They Disembark", phase:"Clarification", relatedTo:"w40k-transports", keywords:["can embarked units be targeted","are units in a transport affected by auras"],
        text:"While embarked, a unit isn't on the battlefield in any sense — it can't be targeted, measured to, or affected by any rule until it disembarks, aside from what happens to it if the Transport itself is destroyed." },
      { id:"w40k-clar-embark-turn-restrictions", title:"Several Situations Block a Unit From Embarking That Turn", phase:"Clarification", relatedTo:"w40k-embark", keywords:["when can i not embark","embark restrictions same turn"],
        text:"A unit can't embark the same turn it was set up on the battlefield — that covers a unit that just disembarked, one that just arrived from a Deep Strike-style ability, and one that just arrived from Reserves, on top of the normal 3-inch and capacity requirements." },
      { id:"w40k-clar-disembark-move-inherits", title:"A Transport's Move Can Limit What Its Passengers Do After Disembarking", phase:"Clarification", relatedTo:"w40k-disembark", keywords:["can i move after disembarking","disembark and move same turn"],
        text:"If the Transport already made a Normal Move before the unit disembarked, that unit counts as having made a Normal Move too — no further movement or charging that turn — but if the Transport Remained Stationary, the disembarked unit can move, shoot, charge, and fight completely normally." },
      { id:"w40k-clar-disembark-cant-remain-stationary", title:"A Disembarked Unit Can't Choose to Remain Stationary", phase:"Clarification", relatedTo:"w40k-disembark", keywords:["can i remain stationary after disembarking","disembark counts as a move"],
        text:"Disembarking already counts as that unit's move for the phase, so it isn't eligible to separately declare Remain Stationary — even a unit that can otherwise act completely normally afterward has technically already moved by getting off the Transport." },
      { id:"w40k-clar-firing-deck-weapon-buff-scope", title:"Firing Deck Attacks Use the Transport's Own Buffs, Not the Passenger's", phase:"Clarification", relatedTo:"w40k-firing-deck", keywords:["does firing deck get my unit's buffs","firing deck weapon abilities"],
        text:"Because the Transport itself counts as being equipped with the passenger's weapon during a Firing Deck attack, an ability that buffs weapons for the passenger's own unit doesn't apply — only buffs that affect the Transport's unit would." },
      { id:"w40k-clar-emergency-disembark-no-charge", title:"A Unit That Emergency Disembarks Can't Charge or Heroic Intervene That Turn", phase:"Clarification", relatedTo:"w40k-emergency-disembark", keywords:["can i charge after emergency disembark","transport destroyed passengers charge"],
        text:"Passengers forced out when their Transport is destroyed follow the normal Disembark placement rules, but on top of that they specifically can't declare a charge or perform Heroic Intervention for the rest of that turn." },
      { id:"w40k-clar-emergency-disembark-vs-explodes", title:"Emergency Disembark Replaces the Transport's Explodes Damage for Passengers", phase:"Clarification", relatedTo:"w40k-emergency-disembark", keywords:["do passengers take explodes damage too","emergency disembark and explodes stacking"],
        text:"Passengers forced out this way aren't also hit by the Transport's own Explodes-type ability — instead they take the separate D6-per-model roll built into Emergency Disembark itself, so the two effects don't stack on the same models." },
      { id:"w40k-clar-transport-capacity-and-restrictions", title:"Embarking Also Depends on Capacity and Keyword Restrictions", phase:"Clarification", relatedTo:"w40k-embark", keywords:["what stops me embarking besides distance","transport capacity restrictions"],
        text:"Getting within 3 inches isn't enough on its own to embark — the Transport also needs enough remaining capacity for that unit, and the unit has to satisfy any keyword or faction restrictions printed on the Transport's own datasheet." },

      // ---- Weapon Abilities (8) ----
      { id:"w40k-clar-extra-attacks-additive", title:"Extra Attacks Weapons Don't Replace a Model's Other Attacks", phase:"Clarification", relatedTo:"w40k-extra-attacks", keywords:["do extra attacks replace my normal attacks","extra attacks weapon rule"],
        text:"A weapon with Extra Attacks is resolved in addition to a model's normal weapon choice, rather than being chosen as an alternative, so a model can make its usual attacks and its Extra Attacks weapon's attacks in the same activation." },
      { id:"w40k-clar-hazardous-per-attacking-model", title:"Hazardous Is Tested Once per Model That Actually Attacked", phase:"Clarification", relatedTo:"w40k-hazardous", keywords:["how many hazardous rolls do i make","hazardous per model or per unit"],
        text:"The Hazardous test is rolled individually for each model that fired or fought with that weapon this activation — not once for the whole unit — so only the models that actually used it risk the mortal wound." },
      { id:"w40k-clar-one-shot-once-per-battle", title:"One Shot Weapons Can't Be Selected Again After Firing", phase:"Clarification", relatedTo:"w40k-one-shot", keywords:["can i fire a one shot weapon twice","one shot weapon reuse"],
        text:"Once a One Shot weapon has been chosen to shoot with, it's used up for the rest of the battle — the model still has it on its profile, but it can't be selected to shoot with again." },
      { id:"w40k-clar-cleave-single-target", title:"Cleave's Bonus Requires All Attacks to Target One Unit", phase:"Clarification", relatedTo:"w40k-cleave", keywords:["does cleave work if i split attacks","cleave single unit requirement"],
        text:"The extra attacks from Cleave only apply if every attack made with that weapon this activation targets the same enemy unit — splitting the weapon's attacks across multiple targets forfeits the bonus entirely." },
      { id:"w40k-clar-melta-half-range", title:"Melta's Damage Bonus Also Needs Half Range", phase:"Clarification", relatedTo:"w40k-melta", keywords:["melta half range requirement","when does melta bonus apply"],
        text:"Like Rapid Fire, the Melta bonus only applies if the target is within half the weapon's printed range — add the melta value to Damage for each wound scored in that case, but not at longer ranges." },
      { id:"w40k-clar-psychic-ignores-both-directions", title:"Psychic Weapons Ignore Bonuses As Well As Penalties", phase:"Clarification", relatedTo:"w40k-psychic", keywords:["does psychic ignore bonuses too","psychic weapon positive modifiers"],
        text:"The Psychic weapon ability cuts both ways — it strips out positive modifiers to BS/WS and the hit roll too, not just negative ones, so a Psychic attack hits purely off the unmodified roll versus the weapon's skill value." },
      { id:"w40k-clar-torrent-still-needs-valid-target", title:"Torrent Skips the Hit Roll, Not Targeting Requirements", phase:"Clarification", relatedTo:"w40k-torrent", keywords:["does torrent ignore line of sight","torrent weapon targeting rules"],
        text:"A Torrent weapon still needs a valid, in-range target chosen the normal way — line of sight, range, and eligibility all still apply. It's only the hit roll itself that's skipped, with every attack counting as a hit." },
      { id:"w40k-clar-conversion-half-range-crit", title:"Conversion Lowers the Critical Hit Threshold at Range, Not the Hit Roll Itself", phase:"Clarification", relatedTo:"w40k-conversion", keywords:["how does conversion work","conversion weapon crit threshold"],
        text:"Conversion doesn't make the weapon easier to hit with in general — at half range or beyond, an unmodified 4+ counts as a Critical Hit instead of needing the usual unmodified 6." },

      // ---- General (8) ----
      { id:"w40k-clar-modifier-cap-scope", title:"The ±1 Modifier Cap Only Applies to Hit and Wound Rolls", phase:"Clarification", relatedTo:"w40k-modifier-cap", keywords:["does the modifier cap apply to charge rolls","what rolls does the plus 1 minus 1 cap cover"],
        text:"The cap of a total +1 or -1 modifier only governs Hit and Wound rolls specifically — it doesn't limit modifiers to Advance rolls, Charge rolls, Damage, or saves, which can stack without that restriction." },
      { id:"w40k-clar-reroll-before-modifier", title:"Rerolls Happen Before Modifiers Are Applied", phase:"Clarification", relatedTo:"w40k-modifier-cap", keywords:["order of rerolls and modifiers","do i modify before or after rerolling"],
        text:"When both a reroll and a modifier apply to the same roll, you reroll the raw dice first and then apply modifiers to the new result — you never apply a modifier, see it fail, and then reroll to try again." },
      { id:"w40k-clar-single-die-reroll-limit", title:"A Die Can Only Be Rerolled Once", phase:"Clarification", relatedTo:"w40k-modifier-cap", keywords:["can i reroll a reroll","reroll the same die twice"],
        text:"Even if two different abilities would each let you reroll the same die, you only get to reroll it a single time — rerolls of rerolls aren't allowed, however many separate sources of reroll are available." },
      { id:"w40k-clar-unmodified-1-always-fails", title:"An Unmodified Roll of 1 Always Fails, No Matter What", phase:"Clarification", relatedTo:"w40k-modifier-cap", keywords:["does a natural 1 always fail","unmodified 1 hit roll"],
        text:"This applies specifically to Hit and Wound rolls — a natural 1 always fails those regardless of any bonuses that would otherwise be enough to succeed, since the modifier cap and the auto-fail rule work together." },
      { id:"w40k-clar-invuln-vs-normal-save-choice", title:"You Take Whichever Save Is Actually Better for That Attack", phase:"Clarification", relatedTo:"w40k-invulnerable-save", keywords:["can i choose which save to use","invulnerable save vs armour save choice"],
        text:"A model with both a normal armour save and an Invulnerable Save isn't locked into one over the other — it uses whichever produces the better result against that specific attack, since AP can worsen the armour save but never touches the Invulnerable one." },
      { id:"w40k-clar-mortal-wounds-no-save", title:"Mortal Wounds Skip Saves Entirely", phase:"Clarification", relatedTo:"w40k-mortal-wounds", keywords:["do mortal wounds allow a save","can i save against mortal wounds"],
        text:"Mortal wounds go straight to reducing a unit's wounds — there's no hit roll, wound roll, or save involved, aside from specific abilities (like certain Feel No Pain effects) explicitly written to work against mortal wounds." },
      { id:"w40k-clar-unit-coherency-two-thresholds", title:"Unit Coherency Has a Closer Rule and a Wider Rule at the Same Time", phase:"Clarification", relatedTo:"w40k-unit-coherency", keywords:["how far apart can my unit be","unit coherency distance rules"],
        text:"Coherency isn't a single distance — every model must be within 2 inches horizontally of at least one other model in the unit, and simultaneously within 9 inches horizontally of every other model in that same unit, both subject to the same 5-inch vertical limit." },
      { id:"w40k-clar-heal-cant-exceed-starting-wounds", title:"Heal Can't Push a Model Above Its Starting Wounds", phase:"Clarification", relatedTo:"w40k-heal", keywords:["can healing overheal a model","heal beyond max wounds"],
        text:"Any Heal effect that would take a model past its own printed Wounds characteristic just wastes the excess — you can't bank extra wounds on a model beyond what it started with, even if the Heal X value would technically allow more." },
    ]
};
